<x-layouts::app.sidebar :title="__($template->exists ? 'Ubah checklist' : 'Buat checklist')">
    <flux:main><div class="mx-auto w-full max-w-[1440px] space-y-6 p-4 sm:p-6 lg:p-8"><div><flux:button href="{{ $template->exists ? route('checklists.show', $template) : route('checklists.index') }}" variant="ghost" icon="arrow-left" wire:navigate>Kembali</flux:button><flux:heading size="xl" class="mt-3">{{ $template->exists ? 'Ubah checklist draft' : 'Buat checklist' }}</flux:heading><flux:subheading class="mt-1">Susun item dengan urutan yang akan dilihat teknisi.</flux:subheading></div><form method="POST" action="{{ $template->exists ? route('checklists.update', $template) : route('checklists.store') }}" class="space-y-6" x-data="checklistBuilder(@js($items->map(fn($item) => ['label' => $item->label, 'input_type' => $item->input_type->value, 'is_required' => $item->is_required, 'photo_required' => $item->photo_required, 'options' => collect($item->options ?? [])->implode(', '), 'help_text' => $item->help_text])->values()))">@csrf @if($template->exists) @method('PUT') @endif<div class="grid gap-6 xl:grid-cols-[minmax(0,1fr)_22rem]"><div class="space-y-6"><section class="lk-card space-y-5 p-5 sm:p-7"><flux:heading size="lg">Informasi template</flux:heading><div class="grid gap-5 sm:grid-cols-2"><div><label for="template_key" class="mb-2 block text-sm font-medium text-foreground">Template key <span class="text-danger">*</span></label><input id="template_key" name="template_key" value="{{ old('template_key', $template->template_key) }}" required placeholder="ac.preventive" class="h-11 w-full rounded-control border border-border bg-surface px-3 text-sm text-foreground">@error('template_key')<flux:error>{{ $message }}</flux:error>@enderror</div><div><label for="service_id" class="mb-2 block text-sm font-medium text-foreground">Layanan terkait</label><select id="service_id" name="service_id" class="h-11 w-full rounded-control border border-border bg-surface px-3 text-sm text-foreground"><option value="">Semua layanan</option>@foreach($services as $service)<option value="{{ $service->id }}" @selected((string)old('service_id', $template->service_id) === (string)$service->id)>{{ $service->name }}</option>@endforeach</select>@error('service_id')<flux:error>{{ $message }}</flux:error>@enderror</div><div class="sm:col-span-2"><label for="name" class="mb-2 block text-sm font-medium text-foreground">Nama checklist <span class="text-danger">*</span></label><input id="name" name="name" value="{{ old('name', $template->name) }}" required class="h-11 w-full rounded-control border border-border bg-surface px-3 text-sm text-foreground">@error('name')<flux:error>{{ $message }}</flux:error>@enderror</div><div class="sm:col-span-2"><label for="description" class="mb-2 block text-sm font-medium text-foreground">Deskripsi</label><textarea id="description" name="description" rows="3" class="w-full rounded-control border border-border bg-surface px-3 py-2 text-sm text-foreground">{{ old('description', $template->description) }}</textarea></div></div></section><section class="lk-card p-5 sm:p-7"><div class="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><flux:heading size="lg">Item pemeriksaan</flux:heading><p class="mt-1 text-sm text-muted-foreground">Gunakan tombol naik/turun sebagai alternatif keyboard untuk mengatur urutan.</p></div><flux:button type="button" variant="outline" icon="plus" x-on:click="addItem">Tambah item</flux:button></div><div class="mt-5 space-y-4"><template x-for="(item, index) in items" :key="item.uid"><article class="rounded-panel border border-border bg-surface-subtle p-4"><div class="flex items-start gap-3"><span class="mt-2 flex size-7 shrink-0 items-center justify-center rounded-full bg-accent-soft text-xs font-semibold text-accent" x-text="index + 1"></span><div class="min-w-0 flex-1 space-y-3"><input :name="`items[${index}][label]`" x-model="item.label" required placeholder="Contoh: Kondisi filter bersih" class="h-10 w-full rounded-control border border-border bg-surface px-3 text-sm text-foreground"><div class="grid gap-3 sm:grid-cols-2"><select :name="`items[${index}][input_type]`" x-model="item.input_type" class="h-10 rounded-control border border-border bg-surface px-3 text-sm text-foreground"><option value="checkbox">Checkbox</option><option value="text">Teks</option><option value="number">Angka</option><option value="choice">Pilihan</option></select><input :name="`items[${index}][options]`" x-model="item.options" :disabled="item.input_type !== 'choice'" placeholder="Pilihan, pisahkan koma" class="h-10 rounded-control border border-border bg-surface px-3 text-sm text-foreground disabled:opacity-50"></div><textarea :name="`items[${index}][help_text]`" x-model="item.help_text" rows="2" placeholder="Petunjuk singkat (opsional)" class="w-full rounded-control border border-border bg-surface px-3 py-2 text-sm text-foreground"></textarea><div class="flex flex-wrap gap-x-5 gap-y-2 text-xs text-muted-foreground"><label class="inline-flex items-center gap-2"><input type="checkbox" :name="`items[${index}][is_required]`" value="1" x-model="item.is_required" class="rounded border-border text-accent focus:ring-accent">Wajib diisi</label><label class="inline-flex items-center gap-2"><input type="checkbox" :name="`items[${index}][photo_required]`" value="1" x-model="item.photo_required" class="rounded border-border text-accent focus:ring-accent">Wajib foto</label></div></div><div class="flex shrink-0 flex-col gap-1"><button type="button" class="rounded-control p-2 text-muted-foreground hover:bg-surface hover:text-foreground disabled:opacity-30" :disabled="index === 0" x-on:click="move(index, -1)" aria-label="Naik"><flux:icon.chevron-up class="size-4" /></button><button type="button" class="rounded-control p-2 text-muted-foreground hover:bg-surface hover:text-foreground disabled:opacity-30" :disabled="index === items.length - 1" x-on:click="move(index, 1)" aria-label="Turun"><flux:icon.chevron-down class="size-4" /></button><button type="button" class="rounded-control p-2 text-danger hover:bg-danger-soft" x-on:click="remove(index)" aria-label="Hapus"><flux:icon.trash class="size-4" /></button></div></div></article></template><div x-show="items.length === 0" class="rounded-panel border border-dashed border-border-strong p-8 text-center"><p class="text-sm text-muted-foreground">Belum ada item. Tambahkan pemeriksaan pertama.</p></div></div></section></div><aside class="space-y-6"><section class="lk-card p-5 sm:p-6"><flux:heading size="lg">Preview mobile</flux:heading><p class="mt-1 text-sm text-muted-foreground">Pratinjau ringkas untuk layar teknisi.</p><div class="mx-auto mt-5 max-w-sm rounded-[1.5rem] border-4 border-primary/80 bg-background p-3 shadow-sm"><div class="rounded-[1rem] bg-surface p-4"><p class="text-xs font-semibold text-accent">CHECKLIST</p><p class="mt-1 text-base font-semibold text-foreground" x-text="document.getElementById('name')?.value || 'Nama checklist'"></p><div class="mt-4 space-y-3"><template x-for="(item, index) in items.slice(0, 5)" :key="'preview-'+item.uid"><div class="rounded-control border border-border p-3"><div class="flex items-start gap-2"><span class="mt-0.5 size-4 rounded border border-border-strong"></span><p class="text-xs font-medium text-foreground" x-text="item.label || 'Item baru'"></p></div><p class="mt-2 text-[10px] text-muted-foreground" x-text="item.input_type + (item.is_required ? ' · wajib' : '')"></p></div></template><p x-show="items.length > 5" class="text-center text-[10px] text-muted-foreground">+ <span x-text="items.length - 5"></span> item lain</p></div></div></div></section></aside></div><div class="flex flex-col-reverse gap-3 border-t border-border pt-5 sm:flex-row sm:justify-end"><flux:button href="{{ $template->exists ? route('checklists.show', $template) : route('checklists.index') }}" variant="ghost" wire:navigate>Batal</flux:button><flux:button type="submit" variant="primary">Simpan draft</flux:button></div></form></div><script>function checklistBuilder(initialItems) { return { items: initialItems.map((item, index) => ({ uid: `${Date.now()}-${index}-${Math.random()}`, label: item.label ?? '', input_type: item.input_type ?? 'checkbox', is_required: Boolean(item.is_required), photo_required: Boolean(item.photo_required), options: item.options ?? '', help_text: item.help_text ?? '' })), addItem() { this.items.push({ uid: `${Date.now()}-${Math.random()}`, label: '', input_type: 'checkbox', is_required: false, photo_required: false, options: '', help_text: '' }); }, remove(index) { this.items.splice(index, 1); }, move(index, offset) { const target = index + offset; if (target < 0 || target >= this.items.length) return; const item = this.items.splice(index, 1)[0]; this.items.splice(target, 0, item); } } }</script></flux:main>
